# Synthetic fixture for LLM-18: the agent runs in us-east-1, its knowledge base in us-west-2.
variable "aws_region" {
  type    = string
  default = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

provider "aws" {
  alias  = "west"
  region = "us-west-2"
}

resource "aws_lambda_function" "agent" {
  function_name = "support-agent"
  role          = aws_iam_role.agent.arn
  handler       = "app.handler"
  runtime       = "python3.12"

  environment {
    variables = {
      BEDROCK_REGION = "us-west-2"
      LOG_LEVEL      = "INFO"
    }
  }
}

resource "aws_opensearchserverless_collection" "kb" {
  provider = aws.west
  name     = "support-kb"
  type     = "VECTORSEARCH"
}

resource "aws_opensearchserverless_collection" "audit" {
  name = "support-audit"
  type = "SEARCH"
}

// Synthetic fixture for LLM-18: a TypeScript agent with a Bedrock client in another Region.
import { BedrockRuntimeClient, ConverseCommand } from "@aws-sdk/client-bedrock-runtime";
import { S3Client } from "@aws-sdk/client-s3";

const assets = new S3Client({ region: "eu-central-1" });

export const bedrock = new BedrockRuntimeClient({
  maxAttempts: 3,
  region: "eu-central-1",
});

export async function ask(prompt: string) {
  return bedrock.send(new ConverseCommand({ modelId: "amazon.nova-lite-v1:0", messages: [] }));
}
